<?php
namespace App\Services\PhaseOne;
use App\Models\TenantRole;
class AccessService {
 public const CATALOG=['contacts.view','contacts.create','contacts.update','contacts.delete','contacts.import','contacts.export','messages.view','messages.send','inbox.manage','snippets.view','snippets.manage','sla.view','sla.manage','campaigns.view','campaigns.manage','campaigns.launch','sales.view','sales.manage','tasks.view','tasks.manage','companies.view','companies.manage','appointments.view','appointments.manage','custom_fields.manage','settings.view','settings.manage','users.view','users.manage','audit.view','audit.export','automation.view','automation.manage','reporting.view','reporting.export'];
 public function ensureRoles(int $tenantId): void { foreach ([['Owner','owner',self::CATALOG],['Administrator','admin',self::CATALOG],['Manager','manager',array_values(array_diff(self::CATALOG,['users.manage','settings.manage']))],['Agent','agent',['contacts.view','contacts.create','contacts.update','messages.view','messages.send','snippets.view','sla.view','campaigns.view','sales.view','tasks.view','tasks.manage','companies.view','appointments.view','appointments.manage']]] as [$name,$slug,$permissions]) { $role=TenantRole::firstOrCreate(['tenant_id'=>$tenantId,'slug'=>$slug],['name'=>$name,'description'=>"Built-in {$name} role",'permissions'=>$permissions,'is_system'=>true]); if($role->is_system){$merged=array_values(array_unique(array_merge($role->permissions??[],$permissions)));if($merged!==($role->permissions??[]))$role->update(['permissions'=>$merged]);} } }
 public function can($user,string $permission): bool { $this->ensureRoles((int)$user->tenant_id); if((int)$user->tenant?->owner_id===(int)$user->id)return true; $fallback=in_array($user->role,['admin','manager','agent'])?$user->role:'agent'; $role=$user->tenantRole ?: TenantRole::where('tenant_id',$user->tenant_id)->where('slug',$fallback)->first(); return $role && in_array($permission,$role->permissions??[],true); }
}
